guide('aidr-platform', ['平台操作：接入、会话与运行证据', 'Platform operations: onboarding, sessions and evidence'],
  ['从客户端详情完成接入配置、状态验收、会话复盘与系统证据查询。', 'Configure onboarding, validate status and review conversation and system evidence from client details.'], [
  ['security-rules', { title: '统一安全规则', paragraphs: ['从全局或单客户端配置进入“安全规则”。一个新增入口、一个编辑弹窗，每条规则配置匹配条件、风险记录、执行前动作和启用状态。'], bullets: ['路径集合独立维护并由多条规则引用；更新同时作用于引用规则，引用中不能删除。', '客户端可继承全局或单独配置，已有混合继承保持动态更新。风险记录启停可独立覆盖。', '测试规则同时返回风险命中与最终动作，不执行命令。保存统一校验并原子发布，失败保留草稿。', '动作按当前 Hook 能力提供；命令动作支持 POSIX 字面条件及单个明确路径。内置复杂行为和 Windows 特有条件用于风险记录。'] },
    { title: 'Unified security rules', paragraphs: ['Open Security rules in global or per-client settings. One Add rule entry and one editor configure conditions, risk recording, pre-execution action and enabled state.'], bullets: ['Maintain named path sets independently and reference them from multiple rules. Updates affect all references; referenced sets cannot be deleted.', 'Clients inherit global rules or use a local override. Legacy mixed inheritance remains dynamic; risk recording can be enabled independently.', 'Test rules shows risk matches and the final action without executing commands. Saving validates and publishes atomically; failures retain drafts.', 'Actions follow current Hook capabilities. Command actions support literal POSIX conditions and one explicit path. Complex built-in behaviors and Windows-specific conditions support risk recording.'] }],
  ['risk-query', { title: '风险查询与配置恢复', paragraphs: ['点击对应表头筛选，风险类型列同时提供严重度与类型。选择立即生效并高亮，最右侧表头可刷新或清空筛选，默认每页 10 条。时间、风险等级和产品列支持全量排序，默认时间降序；排序和筛选回到第一页并保留每页数量。产品可搜索选择，时间范围确认或清空后立即查询。安全规则保存冲突时保留草稿；重新读取会在确认后替换草稿。'] },
    { title: 'Risk queries and settings recovery', paragraphs: ['Filter from column headers; Risk type includes severity and type. Selections apply immediately and highlight the icon. Refresh or clear filters from the rightmost column header; the default page size is 10. Time, severity and product columns sort the full result, with time descending by default. Sorting and filtering reset to page one and retain page size. Search and select a product; confirming or clearing the date range queries immediately. A security settings conflict retains the draft. Confirming Reload replaces it with current settings.'] }],
  ['risk-disposition', { title: '风险处置与重新打开', paragraphs: ['风险详情可选择待处理、接受风险、误报或已解决；填写原因后保存，历史按版本分页展示处理人、状态变化和时间。处置需要客户端查看及修改权限，原因最多 1000 个 Unicode 字符。'], bullets: ['已解决是人工处理声明，实际执行结果与原始证据分别保留。迟到结果不改变处置，新风险独立进入待处理。', '冲突或失败保留草稿，使用重新读取状态后核对并再次提交。风险列表支持状态筛选，智能体汇总保留历史与待处理数量。', '关闭后仍可重新打开；处置历史及系统审计保留，读取证据正文需要独立权限。'] },
    { title: 'Disposition and reopening', paragraphs: ['In risk details, select Open, Accepted risk, False positive or Resolved and save a reason. Paginated history shows revision, reviewer, state change and time. Client view/update permissions are required; reasons allow 1000 Unicode characters.'], bullets: ['Resolved is a human completion declaration. Execution results and evidence remain intact. Late results retain the disposition; new findings start Open.', 'Conflicts and failures preserve the draft. Reload the status, review and submit again. Filter the risk list by disposition; agent summaries retain historical and open counts.', 'Closed findings can be reopened. History and operation audits remain available; evidence content requires separate permission.'] }],
  ['agent-risk-summary', { title: '从智能体查看关联产品风险', paragraphs: ['智能体列表按可见关联设备与产品展示全部已记录风险的高/中等数量、最高严重度及最近时间。点击查看相关风险；有多个范围时先选择设备与产品，然后进入已预填产品筛选的客户端风险页。'], bullets: ['同一行内重复设备/产品只计一次；多个安装入口或智能体共享同一产品范围，跨行数量不可直接求和。Qoder CLI 与共享 Hook 分别列出，安装入口仍需证据确认。', '无实例、未映射产品和无客户端查看权限分别提示；部分实例未映射时显示数量。零条仅表示没有已记录风险；采集覆盖、检测进度和路径配置到风险页查看。', '跳转后的产品筛选可修改，顶部统计始终为设备全部风险；设备级及未映射记录从客户端风险页查看。证据正文仍需独立权限。'] },
    { title: 'Open related product risks from agents', paragraphs: ['The agent list shows high/medium counts, highest severity and latest finding across visible linked devices and products. Choose View related risks, select a scope when needed, and open the client risk page with its product filter prefilled.'], bullets: ['Duplicate device/product pairs count once within a row. Multiple installations or agents can share a product scope, so counts across rows are not additive. Qoder CLI and shared Hooks remain separate entries; installation attribution requires evidence.', 'No instance, unmapped product and missing client view permission have separate states. Partially mapped assets show the number of unmapped instances. Zero only means no findings are recorded; inspect collection coverage, detection progress and path configuration on the risk page.', 'The product filter can be changed after navigation. Top counters remain device-wide. Device-only and unmapped findings are available from the client risk page; evidence content requires its own permission.'] }],
  ['risk-command-rules', { title: '命令规则与测试', paragraphs: ['在全局或客户端配置的“安全规则”列表启停内置规则、添加检测或管控规则；编辑应用到草稿后统一保存。'], bullets: ['自定义条件包括程序名、全部/任一参数、路径参数前缀和紧邻管道目标，支持 Linux/macOS 字面 POSIX 命令与 Windows CMD / PowerShell 字面命令；Windows 程序、参数及路径比较忽略大小写。每行填写一个参数；最多 32 条自定义规则。', '内置规则覆盖保护路径删除、POSIX 下载到 Shell、磁盘格式化、设备写入和保护路径权限修改。Windows 支持 format / Format-Volume、Clear-Disk / dd、del / rd / Remove-Item、icacls 广泛授权与 takeown；WhatIf 不产生内置命中。升级保留既有命令选择，可选择所需内置规则后保存。', '点击测试命令，以当前草稿解析输入；不执行、不保存测试文本、不创建风险。支持显式 cmd /c、powershell / pwsh -Command 包装。外部脚本、diskpart /s、动态 Set-Acl、变量和不支持的选项显示无法解析。', '风险详情保留当次命中规则名称与严重度。读取原始证据后展示当次条件和目标；规则修改、删除不改写历史，旧记录不回算。'] },
    { title: 'Command rules and testing', paragraphs: ['Enable built-ins or add detection/control rules in Security rules under global/client settings. Apply edits to the draft, then save to publish.'], bullets: ['Conditions cover executable, all/any arguments, path-argument prefix and immediate pipeline destination for literal Linux/macOS POSIX and Windows CMD / PowerShell commands. Windows executable, argument and path comparisons are case-insensitive. Enter one argument per line; up to 32 custom rules.', 'Built-ins cover protected-path deletion, POSIX downloads piped to Shell, disk formatting, device writes and protected-path permission changes. Windows supports format / Format-Volume, Clear-Disk / dd, del / rd / Remove-Item, broad icacls grants and takeown; WhatIf produces no built-in match. Upgrades preserve selected commands; select and save additional built-ins to add coverage.', 'Test command parses the current draft without executing commands, storing test text or creating findings. Explicit cmd /c and powershell / pwsh -Command wrappers are supported. External scripts, diskpart /s, dynamic Set-Acl, variables and unsupported options are unresolved.', 'Finding details preserve the original matched rule names and severities. Audited evidence access reveals recorded conditions and targets. Later rule edits/deletion do not rewrite history; legacy records are not recalculated.'] }],
  ['runtime-risks', { title: '运行风险事件', paragraphs: ['进入客户端详情 → 风险事件，查看服务端对已上报证据的规则检测。按严重度、类型、来源、产品及时间筛选。'], bullets: ['当前检测保护路径删除（含普通 rm、rm -f 和递归删除）、支持的下载到 Shell 管道、敏感读取、保护路径变更、Hook 拒绝和系统访问拒绝。客户端 → 全局客户端配置 → 安全规则提供全局默认；单个客户端在客户端详情 → 客户端配置 → 安全规则中分别继承或单独设置启停与规则。新安装默认启用常见敏感与保护路径；升级自动补齐未经修改的初始空配置。已保存的空配置、关闭状态及自定义设置保留，可在路径集合选择内置条目后保存。规则的适用智能体可选一个或多个，全部与具体选项互斥；命中任一所选智能体即可生效，测试入口仍单选。执行前动作按当前条件显示具体限制。WorkBuddy、CodeBuddy IDE、TRAE、TRAE CN、Claude Code、Codex 和 Qoder Hooks 支持平台审批；需升级客户端，等待默认180秒，平台全局可配置30–300秒并支持客户端覆盖。超时拒绝本次调用，每次调用单独审批。自定义路径逐行填写规范绝对路径。每个集合最多 32 项、每项最多 512 UTF-8 字节，无通配符，同时匹配下级路径。', '配置保存需要管理员及客户端/设置修改权限；风险记录设置用于尚未检测的证据，执行前动作按工具策略发布；旧结论保持。首次后台处理当前保留证据，检测进度按已收到的证据计算。', '详情展示命中规则、可读拒绝原因及执行结果；未知结果说明具体原因。点击“处理风险”填写处理方式和原因，取消收起并保留草稿；审批回执按设备和调用关联，已使用审批授权不等同于执行成功；Hook 拒绝记录决策反馈，系统文件变化记录文件操作通知。产品或设备范围不推断具体安装入口，不把不同来源的推测关联当作确定去重。', '点击读取证据内容需要审计正文权限并记录访问审计；原始命令和路径保持原文，过期证据明确标记。日期筛选按本地日期包含开始日和结束日全天。', '手工验收中英文、窄屏、长内容、缺失/迟到结果、权限不足、证据过期、非法路径草稿与配置冲突。'] },
    { title: 'Runtime risk events', paragraphs: ['Open Client details → Risk events for server-side rule detection over received evidence. Filter by severity, type, source, product and time.'], bullets: ['Detection covers protected-path deletion (including plain rm, rm -f and recursive deletion), supported downloader-to-Shell pipelines, sensitive reads, protected-path changes, Hook denial and system access denial. Global defaults are managed under Clients → Global client settings → Security rules. Open Client details → Client settings → Security rules to independently inherit or override status and rules. Fresh installs enable common sensitive and protected paths. Upgrades populate only untouched initial empty defaults. Saved empty configurations, disabled states and custom settings are preserved; select built-in paths and save to update them. Rules can target one or more agents, or All agents exclusively. Any selected agent can match; rule testing still selects one agent. Pre-execution actions show the restriction for the current condition. WorkBuddy, CodeBuddy IDE, TRAE, TRAE CN, Claude Code, Codex and Qoder Hooks support platform approval. Upgrade the client; the default wait is 180 seconds, configurable from 30 to 300 seconds globally or per client. Each call needs its own approval and is denied on timeout. Enter custom normalized absolute paths in Path sets: up to 32 per set and 512 UTF-8 bytes each, without wildcards; descendants are included.', 'Saving requires an administrator with client/settings update permissions. Risk recording settings apply to evidence not yet evaluated; pre-execution actions publish tool policies. Existing findings remain unchanged. Initial background processing covers retained evidence; detection progress covers received evidence.', 'Details show matched rules, readable denial reasons and execution outcomes, with specific reasons for unknown results. Handle risk opens the resolution form; Cancel collapses it and keeps the draft. Approval receipts are linked by device and call; consuming approval does not prove execution success. Hook denial records decision feedback; system file changes record file-operation notifications. Attribution remains at product/device scope; inferred cross-source links do not establish deduplication.', 'Reading evidence content requires audit content permission and records an access audit. Commands and paths remain unchanged; expired evidence is labeled. Date filters include the full start and end dates in local time.', 'Manually validate both languages, narrow layouts, long content, missing/late results, denied access, expired evidence, preserved invalid drafts and configuration conflicts.'] }],
  ['entry', { title: '入口与操作权限', paragraphs: ['进入“客户端管理”，点击设备名称打开详情；一级页签为“概览”“Agent 与资产”“插件接入”“风险事件”“行为审计”“策略与审批”。“行为审计”下再选择“会话活动”“系统事件”或“采集状态”。列表顶部“客户端策略”配置全局默认；设备“策略与审批”中的“采集与治理配置”和“内容与脱敏”配置单机策略。'], bullets: ['使用已授权的客户端凭证连接设备；设备凭证用于设备上报，不应替换成管理员凭证。', '查看设备、查看审计正文、修改设置、执行客户端任务和处理审批是不同权限。没有正文权限时可看到元数据，但不能把空正文当作未采集。', '配置修改须核对目标设备与影响范围。全局更新只影响继承项，单机覆盖需要在该设备处单独检查。'] },
    { title: 'Entry points and permissions', paragraphs: ['Open Clients and click a device name. Detail tabs are Overview, Agents and Assets, Plugin access, Risk events, Behavior audit, and Policies and approvals. Behavior audit contains Session activity, System events and Collection status. Client policies above the device list manages defaults; Collection & governance and Content & redaction under the device’s Policies and approvals manage overrides.'], bullets: ['Connect with an authorized client credential, not an administrator credential.', 'Device viewing, content viewing, settings changes, task execution and approvals are separate permissions. Metadata without body access is not proof that content was never collected.', 'Confirm device and scope before changing settings. Global changes affect inherited settings; inspect device overrides separately.'] }],
  ['overview', { title: '先看概览，再进入证据', paragraphs: ['概览分为资产、行为、风险三个 Tab，共用时间筛选，默认近 7 天，可选近 30 天或最长 30 天的自定义日期。资产展示最新上报的智能体、按目录计数的 Skill（含共享目录）及治理插件；期间治理任务按创建时间统计当前状态，可按状态下钻。行为展示来源、智能体筛选和工具趋势、排行及通道状态。风险展示当前待处理风险与可解释评分，以及期间新增、趋势、类型、智能体和处置分布。图表按首次检测时间统计，点击下钻至风险列表与详情；聚焦图表后可用方向键选择、回车下钻。处置图展示期间新增风险的当前状态。评分按当前保留的待处理高风险×8、中等风险×3形成W，再计算round(100×(1−exp(−W/60)))；0–29低、30–59中等、60–100高。权重尚未按事故数据校准。关闭检测或检测进度未就绪时不显示评分；采集覆盖请核对通道状态。活动统计继续按Agent日志、Hook等来源分别计数。'], steps: [{ title: '确认报告是否新鲜', body: '核对在线状态、最近报告时间、目标版本和实际版本。' }, { title: '定位缺口所在通道', body: '检查日志来源、Hook 安装与接收器、系统权限与采集对象；展开诊断读取稳定原因码。' }, { title: '进入实际记录', body: '从会话活动或系统事件查询测试时段，核对产品、设备、调用及时间。', expected: '能定位到具体事件及其来源。' }], image: image('aidr-platform-overview', '平台客户端概览与通道状态') },
    { title: 'Start with status, then open evidence', paragraphs: ['Overview has Assets, Activity and Risks tabs sharing a date filter: last 7 days by default, 30 days or custom dates up to 30 days. Assets show latest agents, Skill records per directory (including shared directories), and governance plugins. Tasks are filtered by creation time and show current status with drilldowns. Activity includes source/agent filters, trends, rankings and channel status. Risks show the current backlog and explained score, plus new findings, trends, types, agents and dispositions for the period. Charts use first detection time and open the risk list and details; focus a chart and use arrow keys and Enter for keyboard access. Disposition shows the current status of findings detected in the period. For retained open findings, W = high×8 + medium×3; score = round(100×(1−exp(−W/60))). Levels are Low 0–29, Medium 30–59 and High 60–100. Weights have not been calibrated against incident data. Scores are unavailable when detection is disabled or not ready; check channels for collection coverage. Activity statistics continue to count Agent logs, Hooks and other sources separately.'], steps: [{ title: 'Check report freshness', body: 'Inspect connection state, report time, target version and actual version.' }, { title: 'Locate the affected channel', body: 'Inspect log sources, Hook installation/receiver, or system permissions/targets. Expand stable diagnostic codes.' }, { title: 'Open actual records', body: 'Use Session activity or system events for the test period and verify product, device, call and timestamps.', expected: 'A concrete event and its source are identifiable.' }], image: image('aidr-platform-overview', 'Client overview and channel status', true) }],
  ['default-policy', { title: '首次接入的默认行为', paragraphs: ['尚未保存运行治理策略时，默认启用本机发现的 Claude Code / Codex 日志和普通插件 Hook，系统通道关闭，Hook 为仅审计，普通插件按策略自动安装和更新。取得有效平台策略后才协调执行。已有全局或单机覆盖优先；不要把默认值当作当前已应用状态。', '宿主要求的信任、启用和系统授权仍需完成。平台默认策略需要超级管理员修改；审计策略和设备覆盖还受对应设置/设备权限限制。'] },
    { title: 'Defaults on first enrollment', paragraphs: ['Without a saved runtime-governance policy, discovered Claude Code / Codex logs and ordinary plugin Hooks are enabled by default, system collection is off, Hooks use audit-only mode, and ordinary plugin installation/updates follow automatic policy. Coordination requires a valid platform target. Existing global or device overrides take precedence; defaults are not proof of current application.', 'Required host trust, enablement and system authorization remain separate steps. Editing global client defaults requires a super administrator; audit settings and device overrides also require their respective permissions.'] }],
  ['runtime-target', { title: '发布运行治理目标', steps: [{ title: '打开客户端策略 → 采集与治理配置 → 采集与接入', body: '选择 Agent 日志、插件 Hook、系统事件通道，并分别设置日志产品和 Hook 产品；接入方式、自动更新及重试位于“安装、更新与重试”折叠项。' }, { title: '配置接入方式和模式', body: '普通插件需要用户在宿主中完成其要求的审阅；受管接入需要对应授权。Hook 与系统模式分别配置，日志通道只有采集。' }, { title: '预览范围并保存', body: '确认全局默认或单机覆盖，查看生成任务、执行状态、错误码和客户端回执。' }, { title: '核对实际应用', body: '分别核对每个通道的版本和模式。失败时修复原因，再使用“重新应用当前策略”；该操作重试现有目标。' }], image: image('aidr-runtime-policy', '运行治理策略中的三通道与独立模式') },
    { title: 'Publish the runtime target', steps: [{ title: 'Open Client policies → Collection & governance → Collection & setup', body: 'Select Agent logs, plugin Hooks and system events with independent product selections. Access mode, updates and retries are under Installation, updates & retries.' }, { title: 'Choose integration and modes', body: 'Ordinary plugins require applicable native host review; managed integration requires its authorization. Hook and system modes are independent. Logs are collection-only.' }, { title: 'Preview and save', body: 'Confirm global/default versus device scope, then inspect tasks, errors and client receipts.' }, { title: 'Verify actual application', body: 'Check each channel’s version and mode. Resolve failures before Reapply current policy; this retries the saved target.' }], image: image('aidr-runtime-policy', 'Runtime policy channels and independent modes', true) }],
  ['sessions', { title: '阅读会话活动', steps: [{ title: '选择产品与会话', body: '按产品、会话或允许查看的用户问题搜索，核对设备与会话时间。Qoder 视图可能聚合相关入口，但原始来源标识仍保留。' }, { title: '选择轮次及来源', body: '在轮次导航中定位问题，切换“会话日志”“Hook 事件”或“Skill 行为”；Skill 行为按当前会话展示，可在其筛选栏输入原生轮次 ID。未归属记录单独显示，不会自动挂到最近一轮。' }, { title: '检查调用与结果', body: '展开工具输入、命令、目标、结果、退出信息与来源字段。只有前置事件时显示尝试或结果未知；失败结果应与认证状态分别理解。' }, { title: '检查原文与投影', body: '有权限时查看已采集正文及其脱敏/截断标记。按内容范围未采集的字段无法事后恢复。' }], image: image('aidr-session-activity', '会话活动、轮次与工具结果') },
    { title: 'Read session activity', steps: [{ title: 'Choose a product and session', body: 'Filter by product, session or permitted user-question text. Confirm the device and time range. Qoder views can group related entries while preserving raw source identities.' }, { title: 'Choose a turn and source', body: 'Use turn navigation for Session logs and Hook events. Skill activity is scoped to the selected session and has its own native turn ID filter. Unassigned records stay separate.' }, { title: 'Inspect call and result', body: 'Expand tool input, command, targets, result, exit information and source fields. A pre-event alone is an attempt or unknown result; failures and certification are distinct.' }, { title: 'Inspect content and projections', body: 'With permission, read collected content and redaction/truncation markers. Uncollected fields cannot be recovered later.' }], image: image('aidr-session-activity', 'Session activity, turns and tool results', true) }],
  ['models', { title: '模型、Token 与问题显示', bullets: ['日志模型和 Hook 模型按各自来源展示；Auto 表示来源报告为自动选择；实际模型名称见承载调用的网关记录。', '分别查看已采集的系统片段、用户原文和问题摘要。', 'Token 与压缩前后内容只有对应来源真实提供时才有意义。要验证最终请求或网关压缩结果，进入实际承载该调用的网关审计/Trace。', '切换产品或轮次后核对当前选择，分页和搜索只改变查看范围，不扩大采集。'] },
    { title: 'Models, tokens and question display', bullets: ['Log and Hook model metadata retain their respective sources. Auto is a reported automatic choice; check the gateway carrying the call for the actual model name.', 'Review system/context fragments, original user text and the display summary separately.', 'Token and pre/post-compression evidence exists only when the relevant source supplies it. Verify final requests in the gateway audit/Trace that actually carried the call.', 'Confirm product and turn selections after switching. Search and pagination change the view, not collection scope.'] }],
  ['command-ranking', { title: '子命令与命令出现次数', paragraphs: ['终端工具调用次数按可靠调用身份计数，执行前后事件合并为一次；命令出现次数按 Shell 语法解析后能确定程序名的文本出现次数累计。例如一次调用包含三行 sed、rg、rg，工具调用为 1 次，命令出现为 3 次，排行为 rg 2 次、sed 1 次。'], bullets: ['支持换行、分号、&&、||、管道、后台执行、重定向及命令替换。引号和 heredoc 中的普通文本不会被当作命令，循环和函数体按文本计数。', '详情保留已采集原始命令，并按顺序展示子命令、程序名和行号。完整正文、旧命令摘要和解析出的子命令文本均需要审计正文查看权限；无权限时只显示程序名和次数。采集时已省略的内容无法恢复。', '动态程序名保留文本但不加入排行；语法不完整、正文截断或超出解析上限时明确说明，仍保留工具调用次数。解析采用 Bash / POSIX 语法，不执行命令，也不展开变量或解释 bash -c、python -c 等参数内的代码。', '点击程序排行查看包含该程序的工具调用；同一行可能包含多次命令出现。弹框使用标准分页，显示匹配的工具调用总条数；默认每页 30 条，可选择 10、20、30、50、100 条并跳转页码。切换每页条数回到第一页，保留当前来源、Agent 和时间范围。点击“查看记录”直接展开详情。日志与 Hook 分开统计；宿主结果属于整个调用，不能推断每个子命令都已执行或成功。'] },
    { title: 'Subcommands and command occurrences', paragraphs: ['Terminal tool calls use reliable call identities and merge pre/post events into one invocation. Command occurrences count resolved program names in parsed Shell text. One call containing three lines—sed, rg, rg—counts as one tool call and three occurrences, ranked as rg × 2 and sed × 1.'], bullets: ['Supports newlines, semicolons, &&, ||, pipelines, background execution, redirection and command substitution. Ordinary quoted and heredoc text is not a command. Loops and function bodies count textual occurrences.', 'Details preserve captured original commands and list subcommands, programs and line numbers in source order. Full text, legacy command summaries and parsed subcommand text all require audit-content permission. Without it, only program names and counts remain visible. Content omitted during collection cannot be recovered.', 'Dynamic program names retain their text but do not enter rankings. Incomplete syntax, truncated bodies and parsing limits show explicit status while retaining tool-call counts. Parsing uses Bash / POSIX grammar without executing commands, expanding variables or interpreting code inside bash -c or python -c arguments.', 'Select a program ranking to see tool calls containing it; one row may contain multiple occurrences. The dialog uses standard pagination and shows the total number of matching tool calls. Choose 10, 20, 30 (default), 50 or 100 records per page, or jump to a page number. Changing page size returns to page 1 and retains the source, agent and time range. View record opens the details immediately. Logs and Hooks are counted separately. Host outcomes apply to the whole call, not independently to each subcommand.'] }],
  ['system-evidence', { title: '系统事件与关联强度', paragraphs: ['在“客户端详情 → 行为审计 → 系统事件”按产品、进程或实例查看进程树和事件详情，核对事件时间、PID/实例、可执行文件、来源关系及实际模式。进程派生关系和会话关联是不同结论。'], bullets: ['直接匹配、继承归属、推断和未知应保留区别；未知实例不要强行关联到最近会话。', '系统仅审计包含进程和文件创建、修改、重命名、删除通知。修改表示关闭文件时观察到修改标记，不提供文件内容差异，也不是每次写入的完整轨迹；文件允许/拒绝须来自拦截模式的授权记录。', '网络状态与进程/文件采集状态独立，不能用其中一个“运行中”推导另一个正常。'] },
    { title: 'System evidence and attribution strength', paragraphs: ['Open Client details → Behavior audit → System events and inspect trees/details by product, process or instance. Check event time, PID/instance, executable, attribution and actual mode. Process ancestry and conversation association are different claims.'], bullets: ['Keep direct, inherited, inferred and unknown relations distinct. Do not assign unknown instances to the nearest conversation.', 'System audit includes processes and file create/modify/rename/delete notifications. Modify means a modified file was observed at close, not a content diff or every individual write. File allow/deny evidence requires an authorization record from intercept mode.', 'Network status is separate from process/file status. One healthy channel does not establish the other.'] }],
  ['acceptance', { title: '一条可复核的验收路径', bullets: ['记录测试设备、产品入口、时间、会话和调用标识；使用独立测试目录与无敏感内容的输入。', '执行一个成功操作和一个明确失败操作，分别核对宿主结果、日志/Hook、平台 ACK。', '若启用系统采集，重新启动目标 Agent，核对同一测试进程的 exec/exit；不要仅按时间相近匹配。', '断网再恢复，确认待发量与确认序号变化；重复上报不应增加重复的逻辑调用或 Skill 告警。', '验收记录同时写明未验证的平台、宿主版本、权限状态和没有触发的事件。'], link: link('aidr-troubleshooting', '按现象排查问题') },
    { title: 'A reproducible acceptance path', bullets: ['Record device, product entry, time, session and call identity. Use an isolated directory and non-sensitive input.', 'Run one successful and one deliberately failing harmless operation; compare host result, logs/Hooks and platform ACK.', 'For system collection, restart the target Agent and verify the test process’s exec/exit using identity, not time proximity alone.', 'Disconnect and reconnect to verify queued counts and acknowledgement progress. Retries should not duplicate logical calls or Skill alerts.', 'Record untested OS/host versions, permissions and event types that were not triggered.'], link: link('aidr-troubleshooting', 'Troubleshoot by symptom') }],
])

guide('aidr-client', ['客户端：三通道接入与日常操作', 'Client: channel setup and daily operations'],
  ['完成日志来源、Hook 安装、系统采集对象及权限检查，理解停止、退出与补传。', 'Set up log sources, Hooks, system targets and permissions, and understand stopping, exit and queued uploads.'], [
  ['zcode', { title: 'ZCode（macOS 桌面）', paragraphs: ['适配 ZCode 3.16.3 的内置 Agent。会话读取 ~/.zcode/cli/db/db.sqlite；Hook 安装到 ~/.zcode/cli/config.json 的 hooks.events，安装后新建会话。原生 turnId 和工具调用 ID 用于关联，缺失字段保持缺失。', '执行前允许、拒绝和平台审批复用签名授权及一次性回执。等待超时返回拒绝；宿主自身的 Hook 进程失败可能继续执行，应分别检查配置、接收器和事件到达。桌面已验证无害 Bash 调用；完整审批、Skill/MCP 和重读验收使用同版本随包运行程序与本地模型桩。', '插件安装记录、显式插件目录、MCP 配置和 Skill 文件分别发现；配置不代表实际调用。平台、桌面和 Go 客户端需配套升级。仅核验 macOS 内置 Agent，其他框架、独立 CLI 和其他系统未验收。'] },
    { title: 'ZCode (macOS desktop)', paragraphs: ['Adapts the built-in Agent in ZCode 3.16.3. Sessions come from ~/.zcode/cli/db/db.sqlite; Hooks install into hooks.events in ~/.zcode/cli/config.json. Start a new session after installation. Correlation uses native turnId and tool call IDs; missing fields stay absent.', 'Pre-tool allow, deny and platform approval reuse signed, one-time grants and receipts. Approval timeout returns deny. Native Hook process failures may continue execution; check configuration, receiver health and event arrival separately. A harmless desktop Bash call was verified; full approval, Skill/MCP and reread acceptance used the bundled runtime and a local model stub.', 'Plugin installation records, explicit plugin directories, MCP configuration and Skill files are discovered separately. Configuration does not establish invocation. Upgrade the platform, desktop and Go client together. Other frameworks, standalone CLI distributions and operating systems remain unverified.'] }],
  ['prepare', { title: '接入前检查', bullets: ['先连接正确的平台与设备身份，确认设备凭证有效、上报权限和客户端版本。平台先升级，再升级桌面及配套 Go/原生组件。', '分别确认宿主可执行文件、日志目录和 Skill 目录。', '在平台选中所需通道和产品，核对单机覆盖；在客户端检查最近同步时间与失败原因。', '保护代理、证书和本机文件访问配置。连接失败先排查原因，不通过关闭验签或权限控制绕过。'] },
    { title: 'Before onboarding', bullets: ['Connect to the intended platform/device with a valid client credential and upload permission. Upgrade the platform before desktop and companion Go/native components.', 'Confirm host executables, log directories and Skill roots separately.', 'Select channels/products on the platform, inspect device overrides, then check client sync time and errors.', 'Check proxies, certificates and local file access when connections fail; preserve signature and permission checks.'] }],
  ['workspace', { title: '运行治理工作台', paragraphs: ['桌面“运行治理 → 接入与采集”左侧按产品选择，右侧展示日志策略、Hook 安装/信任与操作；顶部汇总共享接收器和上传状态。Qoder 品牌下仍区分共享 Hook 与 QoderWork 等入口。'], bullets: ['切换产品后逐项核对安装、宿主授权、平台启用与事件到达。适用步骤因产品而异。', '共享接收器正常或最近有 ACK 只证明共享通道有活动，不能证明当前选中的产品已产生新事件。', '展开诊断查看连接、协议、策略版本与原因码；优先从附近的“重试”入口恢复失败步骤。'], image: image('aidr-client-integration', '桌面运行治理的产品选择与接入状态') },
    { title: 'Runtime governance workspace', paragraphs: ['Runtime governance → Integration and collection has a product rail and a detail pane for log policy, Hook installation/trust and actions. Shared receiver/upload status appears above. Qoder-branded entries retain separate settings and identities.'], bullets: ['Check installation, applicable host authorization, platform enablement and actual events per product.', 'A healthy shared receiver or recent ACK does not prove new events from the selected product.', 'Expand diagnostics for connection, protocol, policy versions and reason codes. Use the nearby Retry action for the failed step.'], image: image('aidr-client-integration', 'Desktop product selection and onboarding status', true) }],
  ['logs', { title: 'Agent 日志采集', steps: [{ title: '选择日志产品', body: '在运行治理策略启用日志通道和对应产品。' }, { title: '检查来源发现', body: '确认当前用户的宿主日志存在、可读且格式受支持；查看来源状态和覆盖缺口。只读取已适配记录，不运行日志中的命令。' }, { title: '产生新会话', body: '让宿主完成一次简单输入和工具调用，再检查平台会话活动。无法读取或格式不兼容时保留原因，不假定为空会话。' }], paragraphs: ['采集按文件身份和游标增量进行，处理轮转与截断；本地持久化后异步上传。历史缺失、超限、权限和格式问题在覆盖状态中体现。升级不会把旧的不完整证据自动变成完整记录。'] },
    { title: 'Agent log collection', steps: [{ title: 'Select log products', body: 'Enable the log channel and the intended products.' }, { title: 'Inspect source discovery', body: 'Confirm host logs exist for the current user, are readable and use supported formats. Inspect source status and coverage gaps. The collector does not execute commands from logs.' }, { title: 'Create a new session', body: 'Complete a simple input and tool call, then inspect platform Session activity. Read/format failures retain reasons rather than being treated as empty sessions.' }], paragraphs: ['Collection is incremental by file identity and cursor, with rotation/truncation handling, local persistence and asynchronous upload. Missing history, limits, permission and format failures remain visible coverage gaps. Upgrades do not manufacture missing evidence.'] }],
  ['qwenwork', { title: '千问办公（QwenWork CN）', paragraphs: ['已验证 macOS 桌面版 1.4.0 的本地命令 Hook：SessionStart、UserPromptSubmit、PreToolUse、PostToolUse、Stop。用户配置位于 ~/.qwenworkcn/settings.json；安装后开启新会话，确认接收器健康及平台 ACK。', '日志读取 ~/.qwenworkcn/projects 下的原生 JSONL。执行前允许、拒绝和人工审批已通过隔离实机验收；审批按原生调用 ID 与参数绑定。工具 Hook 缺少轮次 ID 时保持缺失，仅按原生日志证据补充关联。当前宿主命令 Hook 超时或退出码 1 会放行，退出码 2 或非法 JSON 会阻断。', '个人 Skill 来自 ~/.qwenworkcn/identity-data/v1/*/skills。安装、启用、Skill 调用和文件读取是不同证据；原生 Skill 名称可能是扩展别名，不推断本地路径。连接器配置为加密存储；本机自定义 MCP 导入返回 LOCAL_IDENTITY_PHASE_RESTRICTED，未验证真实 MCP 调用。共享插件仅报告已安装，启用状态未知。'] },
    { title: 'QwenWork CN', paragraphs: ['Local command Hooks were verified on macOS desktop 1.4.0: SessionStart, UserPromptSubmit, PreToolUse, PostToolUse and Stop. User settings are in ~/.qwenworkcn/settings.json. Start a new conversation after installation and check receiver health and platform ACK.', 'Read native JSONL under ~/.qwenworkcn/projects. Pre-tool allow, deny and human approval passed isolated desktop acceptance. Approval binds the native call ID and parameters. Missing tool Hook turn IDs stay absent; correlation requires native log evidence. The tested host fails open on command Hook timeout or exit 1; exit 2 and malformed JSON block.', 'Personal Skills reside in ~/.qwenworkcn/identity-data/v1/*/skills. Installation, enablement, Skill invocation and file access are separate evidence. Native Skill names may be extension aliases; local paths are not inferred. Connector settings are encrypted. Local custom MCP import returned LOCAL_IDENTITY_PHASE_RESTRICTED, so real MCP invocation remains unverified. Shared plugins are reported as installed with unknown enablement.'] }],
  ['log-locations', { title: '默认日志来源与读取前提', paragraphs: ['以下路径相对于运行客户端的当前用户目录；自定义宿主数据目录、其他系统用户和未适配记录不会因产品名称相同自动纳入。以“来源发现”的实际路径与诊断为准。'], table: { columns: ['产品', '随包目录', '检查项'], rows: [['Claude Code', '~/.claude/projects', '已有会话文件、可读权限、支持的 JSONL 记录'], ['Codex', '~/.codex/sessions', '日期子目录和会话文件、来源覆盖与解析状态'], ['WorkBuddy', '~/.workbuddy/projects', 'macOS 适配目录；检查记录格式与来源发现'], ['Qoder CLI', '~/.qoder/projects', 'macOS CLI 日志产品单独启用；共享 Hook 不是日志开关']] } },
    { title: 'Default log sources and read prerequisites', paragraphs: ['Paths are relative to the user running the client. Custom host data roots, other OS users and unsupported records are not automatically covered by a matching product name. Inspect actual discovered paths and diagnostics.'], table: { columns: ['Product', 'Bundled root', 'Check'], rows: [['Claude Code', '~/.claude/projects', 'Existing conversations, readable files and supported JSONL records'], ['Codex', '~/.codex/sessions', 'Date directories, conversation files, source coverage and parsing state'], ['WorkBuddy', '~/.workbuddy/projects', 'macOS adapter; inspect format and source discovery'], ['Qoder CLI', '~/.qoder/projects', 'Enable macOS CLI logs separately; shared Hooks do not enable logs']] } }],
  ['hooks', { title: '插件 Hook 接入', steps: [{ title: '安装对应配置', body: '选择产品并使用接入/安装入口。平台允许用户自行接入时，本机操作会申请对应策略；安装成功与平台已启用仍分别确认。' }, { title: '完成宿主要求的审阅', body: '普通 Codex/Claude 等插件需要宿主要求的信任或启用。设置型 Hook 依适配流程配置，不套用其他产品的授权步骤。' }, { title: '重新开始会话', body: '安装后开启新会话，触发受支持的工具事件，再检查接收器和平台记录。' }, { title: '更新或移除', body: '使用对应产品操作，查看任务和宿主状态。移除范围为本产品安装的配置。' }], callout: { type: 'note', title: '普通插件与受管接入', body: '受管接入涉及独立的管理授权及原生加载证据，不能把普通安装成功解释成受管授权。不要手动覆盖宿主中无关的自定义配置。' } },
    { title: 'Plugin Hook onboarding', steps: [{ title: 'Install the matching configuration', body: 'Select a product and use its connect/install action. If user enrollment is allowed, the action requests the product policy. Installation and platform enablement are still separate.' }, { title: 'Complete host-required review', body: 'Ordinary Codex/Claude integrations require applicable native trust or enablement. Settings-based Hooks follow their own adapter flow.' }, { title: 'Start a new conversation', body: 'After installation, open a new session, trigger a supported tool event and check receiver and platform records.' }, { title: 'Update or remove', body: 'Use the product action and inspect task/host status. Removal covers the configuration installed by this product.' }], callout: { type: 'note', title: 'Ordinary plugins versus managed integration', body: 'Managed integration has separate authorization and native loading evidence. Ordinary installation is not managed authorization. Preserve unrelated host customizations.' } }],
  ['system', { title: '系统采集：选择对象并开始', steps: [{ title: '平台启用系统通道及范围', body: '在系统采集策略配置允许产品与选择方式。平台指定时必须满足要求；客户端选择时只能从允许范围中选择有效安装。' }, { title: '发现并选择可执行文件', body: '进入“Agent 运行治理 → 系统采集”。支持采集对象选择的版本可刷新发现结果并核对安装路径；若页面只有“采集控制”和“最近系统事件”，先按当前版本读取平台策略中的程序范围，需要本机选择时升级配套客户端和采集组件。' }, { title: '检查组件与权限', body: '当前 macOS 路径需要可运行的 ES 原生组件、管理员授权、完整磁盘访问权限及有效签名策略。管理员授权与 FDA 不互相替代。' }, { title: '开始采集并重启目标 Agent', body: '只有原生订阅后的健康报告确认“采集中”。在策略生效或模式切换后重新启动目标 Agent，核对进程归属。' }, { title: '查看事件与上传', body: '分别查看进程/文件状态、网络快照状态、最近事件、待上传和最近确认。', expected: '选定目标的新事件及对应上传确认可查询。' }], image: image('aidr-client-system', '原生 Dev 客户端的系统采集控制与历史事件（截图时已停止）') },
    { title: 'System collection: select targets and start', steps: [{ title: 'Enable channel and scope on the platform', body: 'Configure allowed products and selection mode. Platform-required mode must satisfy required products; client selection is restricted to allowed, available installations.' }, { title: 'Discover and select executables', body: 'Open Agent Runtime Governance → System collection. Versions with target selection support discovery and executable selection. If only Collection controls and Recent system events are present, the installed version uses platform-scoped programs; upgrade the matching client and collector for local target selection.' }, { title: 'Check components and permissions', body: 'The current macOS path needs a runnable ES component, administrator authorization, Full Disk Access and valid signed policy. Administrator authorization does not replace FDA.' }, { title: 'Start and restart the target Agent', body: 'Only native subscription health confirms Collecting. Restart the target after policy application or mode changes to establish attribution.' }, { title: 'Inspect events and uploads', body: 'Check process/file state, separate network snapshots, recent events, queued records and acknowledgements.', expected: 'New events for selected targets and corresponding upload confirmations are queryable.' }], image: image('aidr-client-system', 'Native Dev client collection controls and historical events (stopped at capture time)', true) }],
  ['distribution', { title: '系统采集的发行前提', callout: { type: 'warning', title: '正式发行要求', body: '当前 macOS 开发路径的既有验证包含 SIP 关闭、ad-hoc 签名环境。正式交付还需要 Developer ID、Apple Endpoint Security 授权与公证。' }, paragraphs: ['Windows/Linux 的日志适配或交叉编译通过不表示已有同等原生系统采集和控制。部署前逐项核对实际交付组件、系统版本、权限及产品适配。'] },
    { title: 'System collector distribution prerequisites', callout: { type: 'warning', title: 'Production distribution requirements', body: 'Existing macOS development verification includes SIP-disabled, ad-hoc-signed environments. Production delivery requires Developer ID, Apple Endpoint Security authorization and notarization.' }, paragraphs: ['Windows/Linux log support or cross-compilation does not establish equivalent native system collection/control. Check delivered components, OS version, permissions and product adapters before rollout.'] }],
  ['lifecycle', { title: '停止、退出、离线与恢复', table: { columns: ['操作/状态', '需要理解的行为'], rows: [
    ['TeleAgent 模型代理', '独立 macOS 用户级服务，客户端关闭、退出、重启或更新时持续转发模型请求。工具审核仍依赖 Hook 接收器；模型结果与工具授权分别查看对应调用记录。'],
    ['关闭客户端窗口', '客户端和 Hook 接收器继续在后台运行，工具审批和事件上传保持工作。通过托盘“打开客户端窗口”或 macOS Dock 恢复窗口。托盘菜单随客户端语言切换。Windows/Linux 在托盘尚未初始化时保留最小化窗口。'],
    ['最小化或切换页面', '采集继续运行，各通道状态独立显示。'], ['退出桌面应用', 'Hook 接收器与日志采集在主后台服务内持续运行；TeleAgent 模型代理独立运行。退出或重启桌面应用不停止这些服务。系统采集应使用“停止采集”结束。'], ['停止系统采集', '停止订阅并回收原生进程，再限时补传；停止成功和队列排空分开展示。'], ['重启机器', '当前系统采集需要手动再次开始；重新检查授权和原生状态。'], ['平台不可达', '有效缓存与未确认队列保留，重连后重试；有界队列和覆盖缺口仍需监控，不能承诺无限历史。'], ['停用上报或审计', '核对上报许可、采集开关与通道开关，三者不是同一动作；已有待发数据的处理遵循队列/生命周期契约。'],
  ] } },
    { title: 'Stop, exit, offline and recovery', table: { columns: ['Action / state', 'Behavior to understand'], rows: [
    ['TeleAgent model proxy', 'An independent per-user macOS service keeps forwarding model requests across client window closure, quit, restart and updates. Tool review still needs the Hook receiver. Review the corresponding call records for model results and tool authorization.'],
    ['Close the client window', 'The client and Hook receiver keep running in the background, including tool approval and event uploads. Reopen from the tray or macOS Dock. Tray labels follow the client language. Windows/Linux retain a minimized window until the tray is initialized.'],
    ['Minimize or switch pages', 'Collection continues; each channel reports its own state.'], ['Quit the desktop application', 'The main background service keeps Hook reception and log collection running; the TeleAgent model proxy runs independently. Quitting or restarting the desktop does not stop these services. Use Stop collection to stop system collection.'], ['Stop system collection', 'Stop subscriptions and reclaim the native process, then drain for a bounded period. Stopped and queue-empty are distinct.'], ['Reboot', 'Current system collection requires manually starting again and rechecking authorization/native state.'], ['Platform unavailable', 'Valid cached policy and unacknowledged records remain for retry. Monitor bounded queues and coverage gaps; retention is not unlimited.'], ['Disable upload or audit', 'Upload permission, audit collection and channel selection are separate controls. Pending data follows existing queue/lifecycle rules.'],
  ] } }],
])

guide('aidr-policies', ['策略、工具规则、审批与数据范围', 'Policies, tool rules, approvals and data scope'],
  ['区分运行目标、工具控制、系统策略和采集隐私设置，按实际回执验证生效。', 'Separate runtime targets, tool control, system policy and content/privacy settings, then verify actual application.'], [
  ['layers', { title: '四类配置分别负责什么', table: { columns: ['配置', '职责', '验证位置'], rows: [
    ['客户端策略 → 采集与治理配置 → 采集与接入', '通道、产品、接入方式、Hook/系统模式、重试目标', '协调任务与各通道实际版本/模式'], ['客户端配置 → 安全规则；策略与审批 → 审批记录', 'Hook 拦截模式中的工具允许、拒绝与申请审批规则', '有效规则版本、具体调用决策与审批记录'], ['策略与审批 → 系统策略', '可执行文件归属、采集对象、文件规则及原生控制', '签名策略、采集对象与原生事件'], ['客户端策略 → 内容与脱敏', '正文范围、脱敏、保留期限、Skill 使用认证与告警', '客户端策略报告、后续事件的策略快照'],
  ] } }, { title: 'Four distinct configuration responsibilities', table: { columns: ['Configuration', 'Responsibility', 'Verify'], rows: [
    ['Client policies → Collection & governance → Collection & setup', 'Channels, products, setup, Hook/system modes and retry targets', 'Coordination tasks and actual per-channel version/mode'], ['Client settings → Security rules; Policies and approvals → Approval requests', 'Hook allow, deny and approval rules in intercept mode', 'Effective rule version and individual decisions/approvals'], ['Policies and approvals → System policy', 'Executable attribution, targets, file rules and native control', 'Signed policy, targets and native events'], ['Client policies → Content & redaction', 'Content scope, redaction, retention and Skill certification/alerts', 'Client reports and subsequent event policy snapshots'],
  ] } }],
  ['modes', { title: '仅审计与拦截模式', paragraphs: ['Agent 日志始终是采集通道。Hook 与系统防护可以分别选择模式；保存后等待客户端应用，不能只看配置下拉框。'], table: { columns: ['模式', 'Hook', '系统'], rows: [
    ['仅审计', '记录支持的宿主事件；接收器采集故障不应阻止普通工具执行', '采集归属明确的进程与文件变化通知，不执行文件授权决策'], ['拦截', '按有效签名规则允许、拒绝或请求审批；需宿主可靠前置回调', '额外执行已支持的文件授权与进程响应；需对应原生能力及权限'], ['保留原有模式/未知', '检查旧协议或缺失报告，不推测为仅审计', '核对实际模式、版本与报告时间，必要时升级组件'],
  ] }, callout: { type: 'note', title: '控制故障不能按审计故障解释', body: '仅审计接收故障的放行语义不适用于未知控制状态。定位拒绝时先看错误码、有效规则、策略版本、实际模式和宿主映射。' } },
    { title: 'Audit-only and intercept modes', paragraphs: ['Agent logs remain collection-only. Hook and system modes are independent. After saving, check application reports rather than the configuration selector alone.'], table: { columns: ['Mode', 'Hook', 'System'], rows: [
    ['Audit only', 'Records supported callbacks; audit receiver failure should not block ordinary tools', 'Attributed process and file-change notifications; no file authorization decisions'], ['Intercept', 'Signed rules allow, deny or request approval; requires reliable native pre-execution callbacks', 'Supported file authorization and process responses require native capability/permissions'], ['Preserve previous / unknown', 'Inspect legacy protocol or missing reports; do not infer audit-only', 'Check actual mode, version and freshness; upgrade components if necessary'],
  ] }, callout: { type: 'note', title: 'Control failures differ from audit failures', body: 'Audit-only failure semantics do not apply to unknown control state. For a denial, inspect error code, effective rule, policy version, actual mode and adapter mapping first.' } }],
  ['rules', { title: '编写并预览工具规则', steps: [{ title: '选择适用范围', body: '确认设备、产品/实例与工具范围，避免把测试规则误设成所有产品通用。' }, { title: '设置匹配和动作', body: '按页面支持的命令、工具、路径等条件配置允许、拒绝或申请审批。具体宿主不支持的动作不能仅靠配置变为可用。' }, { title: '使用规则预览', body: '输入代表性的工具参数，检查命中规则、匹配字段和动作；预览不是实际宿主执行证明。' }, { title: '发布并验证', body: '检查客户端已获取版本，再在隔离会话验证匹配、未匹配及失败结果。保留具体决策证据。' }], paragraphs: ['当前 Hook 工具规则发布后持续有效，直到新版本替换或管理员撤销；旧签名规则仍按其原有效期处理。具体调用审批仍有独立的截止、消费和撤销语义，不能与规则寿命混淆。'], image: image('aidr-tool-rules', '工具规则预设、匹配条件与处理方式') },
    { title: 'Write and preview tool rules', steps: [{ title: 'Select the scope', body: 'Confirm device, product/instance and tools. Avoid applying a test rule to every product accidentally.' }, { title: 'Configure matching and action', body: 'Use supported command, tool and path conditions with allow, deny or approval. Configuration cannot create an action that a host adapter does not support.' }, { title: 'Preview the rule', body: 'Use representative arguments to inspect the matched rule, fields and action. A preview is not native execution evidence.' }, { title: 'Publish and verify', body: 'Confirm the client obtained the revision, then validate matched, unmatched and failed cases in an isolated session.' }], paragraphs: ['Current Hook tool rules persist until replaced or revoked; legacy signed rules retain their original lifetime. Individual approvals still have separate deadlines, consumption and revocation semantics.'], image: image('aidr-tool-rules', 'Tool presets, match conditions and handling', true) }],
  ['system-control', { title: '系统对象、文件规则与进程响应', steps: [{ title: '设置允许采集的产品与选择方式', body: '在系统采集配置中选择平台指定或本机选择范围。客户端重新发现实际可执行文件并应用，核对配置版本和实际采集状态。' }, { title: '按需配置高级系统规则', body: '在高级规则中设置程序路径、规则 ID、文件路径、作用主体及允许/拒绝动作；核对未知主体和策略过期时的处理方式，再使用预览检查匹配。系统签名策略有效期与 Hook 工具规则寿命不同。' }, { title: '发布并核对回执', body: '检查目标版本、已应用版本、签名及设备续约状态。修改根程序或采集对象后重启目标 Agent；历史配置载入只填充草稿，发布后才产生新的目标。' }, { title: '检查实际文件与进程结果', body: '仅在有效拦截模式及所需权限具备时验证文件允许/拒绝。进程终止只对平台确认可响应的实例显示可用操作；确认目标、提交后继续检查任务回执和退出事件，不能仅凭 PID 或按钮成功认定已终止。' }], callout: { type: 'note', title: '操作系统证据与宿主会话分开核对', body: '系统高级规则与 Hook 工具规则分别配置。规则预览、下发成功和原生实际执行是三个不同的验收步骤。' } },
    { title: 'System targets, file rules and process responses', steps: [{ title: 'Choose products and selection mode', body: 'Set platform-required or locally selectable system targets. Rediscover actual executables on the client, apply them and compare configuration revision with collection state.' }, { title: 'Configure advanced rules when needed', body: 'Set executable roots, rule IDs, file paths, actor scope and allow/deny actions. Check unknown-actor and expired-policy handling, then preview matching. Signed system-policy lifetime differs from Hook tool-rule lifetime.' }, { title: 'Publish and inspect receipts', body: 'Check target/applied revisions, signatures and device renewal. Restart target Agents after root or scope changes. Loading history fills a draft; publishing creates the new target.' }, { title: 'Verify file and process outcomes', body: 'Validate file allow/deny only with effective intercept mode and required privileges. Process termination is available only for verified eligible instances. Confirm the target, submit and inspect the receipt plus exit evidence; a PID or successful button action alone does not prove termination.' }], callout: { type: 'note', title: 'OS evidence and host sessions are separate checks', body: 'System rules and Hook tool rules are configured separately. Preview, delivery and actual native execution are separate acceptance steps.' } }],
  ['approvals', { title: '处理一次调用审批', bullets: ['确认申请对应的设备、产品、会话、工具、命令/目标及规则，必要时展开原始证据。', '允许或拒绝只针对申请所绑定的调用与有效范围；超时、取消、已经消费或已撤销的审批不能当作新的通行证。', '审批完成后查看宿主返回和终态回执。', '审计关闭时，依赖持久证据的审批可能返回明确拒绝原因；不能只打开审批按钮而不满足证据前提。'] },
    { title: 'Handle an individual approval', bullets: ['Verify device, product, session, tool, command/targets and matching rule; expand evidence where needed.', 'Allow/deny applies to the bound call and scope. Expired, cancelled, consumed or revoked approval is not reusable permission.', 'After the decision, check host result and terminal receipt.', 'Approvals requiring durable evidence can be explicitly rejected when audit collection is disabled. The evidence prerequisites still apply.'] }],
  ['content', { title: '正文范围、脱敏与大小限制', paragraphs: ['进入“客户端策略 → 内容与脱敏”，在直接展开的“扩展内容采集”中分别配置用户输入、模型回复、工具输出、文件正文和命令正文；“敏感信息脱敏”独立展示。正文选择与行为元数据不同；不应为查看命令而无差别开启所有正文。'], bullets: ['五项扩展正文默认关闭；默认脱敏开启。以当前保存策略及客户端快照为准，关闭脱敏后新采集内容可能包含敏感数据。', '单片段和单事件有字节上限；先按所选策略脱敏，再截断，并保留截断/脱敏标记。', '保存只作用于后续采集；历史正文、旧游标及冻结待发批次不重写。没有采集的内容和已脱敏内容不能恢复。', '用户输入、代码、命令、文件路径和原始证据保持原文；界面切换语言不会翻译证据。'], image: image('aidr-content-policy', '审计正文范围、脱敏和保留设置') },
    { title: 'Content scope, redaction and limits', paragraphs: ['Open Client policies → Content & redaction and configure Additional content collection directly: input, model replies, tool output, file bodies and command bodies. Sensitive data redaction is shown in a separate section. These are distinct from behavior metadata; enabling every body is not necessary just to inspect a command.'], bullets: ['All five additional content options default to off; redaction defaults to on. Verify saved policy and client snapshots. Disabling redaction can expose sensitive data in subsequent collection.', 'Fragment and event byte limits apply. Selected redaction runs before truncation, with explicit markers.', 'Changes affect subsequent collection. Historical content, cursors and frozen batches are not rewritten. Uncollected or already redacted content cannot be restored.', 'Inputs, code, commands, paths and evidence retain their original language when the UI language changes.'], image: image('aidr-content-policy', 'Audit content, redaction and retention settings', true) }],
  ['content-limits', { title: '正文上限如何设置', table: { columns: ['参数', '当前默认与范围', '使用建议'], rows: [['单片段正文', '默认 1024 字节；256–32768 字节', '中文通常占多个 UTF-8 字节，按实际业务片段评估。'], ['单事件正文总量', '默认 2048 字节；256–32768 字节', '不得小于单片段上限；每事件最多 4 个正文片段。'], ['适用时间', '客户端同步成功后的新增采集', '提高上限不会补齐历史截断内容。']] } },
    { title: 'Choosing content limits', table: { columns: ['Setting', 'Current default and range', 'Guidance'], rows: [['Per fragment', '1024 bytes by default; 256–32768 bytes', 'UTF-8 characters may use multiple bytes; assess representative fragments.'], ['Per event', '2048 bytes by default; 256–32768 bytes', 'Must be at least the fragment limit; at most 4 body fragments per event.'], ['Application', 'New collection after successful client sync', 'Larger limits do not restore truncated history.']] } }],
  ['retention', { title: '保留、补传和策略应用', paragraphs: ['平台日志、Hook 和系统审计历史默认保留 7 天，可配置 1–365 天，按接收时间计算。新版客户端收到平台 ACK 后释放本地日志正文，去重元数据按 ACK 时间保留；未确认队列与冻结批次保持重试身份。逻辑淘汰不承诺清除 SQLite 页、WAL 或备份的物理残留。'], bullets: ['审计历史已淘汰与采集缺口是不同状态；遇到内容过期应查看保留期限，而不是反复重采旧日志。', '策略依设备、流、序号和凭据快照核对；离线客户端沿用有效缓存，恢复后同步。', '保存版本、客户端最近报告版本、报告时间与实际事件快照分开核对。', '更改保留期限、扩大正文或关闭脱敏前，阅读保存预览及影响提示。'] },
    { title: 'Retention, retries and policy application', paragraphs: ['Platform log, Hook and system audit history defaults to 7 days (configurable from 1–365), measured from receipt. Updated clients release local log bodies after platform ACK and retain deduplication metadata from ACK time. Unacknowledged queues and frozen batches retain retry identity. Logical expiry does not promise physical erasure from SQLite pages, WAL or backups.'], bullets: ['Expired history differs from a collection gap. Inspect retention rather than repeatedly rereading old logs.', 'Policy receipts bind device, stream, sequence and scope. Offline clients use valid cached policy and synchronize after reconnecting.', 'Compare saved version, latest reported version/time and event snapshots separately.', 'Read impact previews before shortening retention, widening content scope or disabling redaction.'] }],
])

guide('aidr-skill-audit', ['Skill 使用认证与性能策略', 'Skill-use certification and performance policy'],
  ['区分内容摘要、平台验签、当前授权和宿主结果，并配置后台核对的性能预算。', 'Separate digests, signatures, current authorization and host outcomes, and configure background check budgets.'], [
  ['flow', { title: '一次核对怎样完成', steps: [{ title: '识别真实使用证据', body: '产品适配器提取明确的 Skill 调用或单文件读取。用户提及、搜索和目录枚举不计为调用。' }, { title: '后台观察本地内容', body: '日志采集器可靠定位实际目录后计算 SHA-256 摘要，或按策略复用历史观察。客户端计算摘要，不使用平台私钥签名。' }, { title: '平台验签与查状态', body: '平台优先依据安装版本/路径，再核对批准摘要、签名、注册、审批、撤销与可确认的智能体授权。' }, { title: '展示结论和实际结果', body: '认证结论、内容观察时间和宿主加载/读取结果分别查看；平台核对时间在记录中直接展示，明确不通过按策略生成告警。' }], callout: { type: 'note', title: '此功能为后台审计', body: '摘要在后台采集，使用观察时的文件内容。缺少内容观察时保持待确认，可从详情请求重新采集。加载前阻断需在 Loader、Hook 或 SDK 中接入同步校验。' } },
    { title: 'How a check works', steps: [{ title: 'Identify explicit use evidence', body: 'Adapters extract explicit Skill invocations or single-file reads. Mentions, searches and directory listings are not invocations.' }, { title: 'Observe local content in the background', body: 'The log collector resolves the actual directory and computes SHA-256 or reuses a prior observation. The client computes a digest, not a signature with the platform private key.' }, { title: 'Verify signature and registry state', body: 'The platform prefers installation version/path, then checks approved digest, signature, registration, approval, revocation and identifiable Agent authorization.' }, { title: 'Display certification and outcome separately', body: 'Certification, content observation time and host outcome remain distinct. The record shows the platform check time directly. Definite failures follow alert policy.' }], callout: { type: 'note', title: 'This is background audit', body: 'Digests are collected in the background from files at observation time. Missing content observations remain pending; eligible clients can request recollection from record details. Pre-load blocking requires synchronous checks in the Loader, Hook or SDK.' } }],
  ['status', { title: '如何解释认证状态', table: { columns: ['状态', '含义与处理'], rows: [
    ['已认证', 'registry 模式下批准内容匹配且签名验证通过；strict 模式还须通过实例授权。宿主结果独立展示。'], ['内容已认证 · 授权未知', 'strict 模式下内容认证通过，但无法唯一确定授权主体。'], ['内容与批准版本不一致', '观察到的摘要不符；核对路径与版本，按授权流程恢复可信版本。'], ['内容已认证 · 未授权给此智能体', 'strict 模式下内容认证通过，但智能体未启用或未获此 Skill 授权。'], ['内容未登记 / 未通过准入审批 / 已撤销', '明确平台状态不满足要求；按状态处理，不能笼统归为验签失败。'], ['认证状态待确认', '缺少路径、摘要或身份；读取超限/失败；平台查询不可用；均需保留原因。'], ['已发起调用或读取 / 宿主确认加载或读取 / 已拒绝 / 失败 / 执行结果未确认', '操作结果维度，与上述认证结论独立。'],
  ] } },
    { title: 'Interpret certification states', table: { columns: ['State', 'Meaning and next step'], rows: [
    ['Certified', 'Registry mode requires approved matching content and a verified signature; strict mode also requires Agent authorization. Host outcome is separate.'], ['Content certified · authorization unknown', 'In strict mode, content is certified but the authorization subject is not uniquely established.'], ['Content differs from approved version', 'Observed digest differs; check path/version and restore through authorized procedures.'], ['Content certified · not authorized for this Agent', 'In strict mode, content is certified but the Agent is inactive or lacks Skill authorization.'], ['Unregistered / unapproved / revoked', 'A definite registry or authorization requirement failed. These are not all cryptographic signature failures.'], ['Certification pending', 'Missing path/digest/identity, read limit/failure or unavailable platform query; retain the specific reason.'], ['Started / host confirmed / failed / unknown', 'The operation-outcome dimension, independent of certification.'],
  ] } }],
  ['review', { title: '查看记录并处理待确认', steps: [{ title: '筛选记录', body: '会话列表、行为表格、记录详情分栏显示。支持 Skill/路径、行为、结果、认证和原生轮次筛选。单批尚无匹配但仍有记录时继续查找，游标耗尽才是最终空结果。' }, { title: '沿时间线核对证据', body: '点击记录查看操作证据、原内容观察、新采集观察和平台核对变更。明确拒绝独立显示，冲突结果保持未知。Skill 页签显示会话行为总数；仅有正文片段且原记录可用时显示“查看调用内容”入口，直接展示输入或输出，按设备及调用身份核对归属，正文沿用内容权限与保留策略。' }, { title: '按原因处理待确认', body: '刷新平台状态只读取平台；请求重新采集需要修改权限、在线客户端、新版采集能力和唯一可信来源。重新采集依据 Skill 认证核对开关，与脱敏开关分别配置。客户端读取前获取当前策略，最长只读采集 30 秒；原调用证据保持不变。' }, { title: '检查任务和新结论', body: '任务支持防重复提交、过期后重试和持久回执。策略变化会使旧回执失效。收到采集回执后查看认证结论；核对历史从升级后开始记录，受审计保留周期约束。' }] },
    { title: 'Review records and resolve pending checks', steps: [{ title: 'Filter records', body: 'Sessions, the activity table and record details use separate panes. Filter by Skill/path, behavior, outcome, certification or native turn. An empty batch may still offer Continue searching until its cursor is exhausted.' }, { title: 'Follow the evidence timeline', body: 'Inspect operation evidence, original and recollected content observations, and changes in registry checks. Explicit denials are separate; conflicting outcomes remain unknown. The Skill tab shows the session activity count. View invocation content opens input/output for available records with content fragments. Evidence identity, content permissions and retention still apply.' }, { title: 'Resolve the stated reason', body: 'Registry refresh only reads platform state. Recollection needs update permission, an online upgraded client and a unique trusted source. Recollection follows the Skill audit switch, independently of redaction. The worker fetches current policy before a read-only observation bounded to 30 seconds; original call evidence is retained.' }, { title: 'Review the task and conclusion', body: 'Tasks support duplicate protection, expiry, retries and durable receipts. Changed policy invalidates stale receipts. After receiving a receipt, review certification; check history starts after upgrade and follows audit retention.' }] }],
  ['settings', { title: '核对频率与资源预算', paragraphs: ['全局入口：客户端管理 → 客户端策略 → 内容与脱敏 → Skill 使用审计。单机入口：设备详情 → 策略与审批 → 内容与脱敏。文件数、单文件大小、总量和并发设置位于“高级：资源上限”折叠项。'], table: { columns: ['参数', '默认值', '含义'], rows: [
    ['内容核对方式', '首次使用、变化或到期时计算', '也可选每次使用后台重算；两者均不阻断工具。'], ['摘要最长复用时间', '300 秒', '复用前仍检查文件元数据；到期全量读取，保留原观察时间。'], ['平台状态刷新间隔', '30 秒', '独立刷新审批、撤销和授权；排队或离线会延迟，不是 SLA。'], ['最大并发', '1', '采集器上限，当前顺序路径不会因调大而自动并行。'], ['最大文件数', '256', '超限保留待确认。'], ['单文件 / 单次读取上限', '2 MiB / 8 MiB', '单文件不能超过总量；超限不采集一个不完整摘要冒充完整目录。'],
  ] }, image: image('aidr-skill-policy', 'Skill 使用审计的频率、资源与告警策略') },
    { title: 'Check frequency and resource budgets', paragraphs: ['Global: Clients → Client policies → Content & redaction → Skill use audit. Device: Client details → Policies and approvals → Content & redaction. File counts, file/total sizes and concurrency are under Advanced: resource limits.'], table: { columns: ['Setting', 'Default', 'Meaning'], rows: [
    ['Content check mode', 'First use, change or expiry', 'Alternatively recompute on each use in the background; neither blocks tools.'], ['Maximum digest reuse', '300 seconds', 'Check metadata before reuse and fully read after expiry; preserve observation time.'], ['Platform status refresh', '30 seconds', 'Independent approval/revocation/authorization refresh; backlog/offline delays are possible, not an SLA.'], ['Maximum concurrency', '1', 'An upper bound; increasing it does not parallelize the current sequential path.'], ['Maximum files', '256', 'Limit violations remain pending.'], ['Per-file / total read limit', '2 MiB / 8 MiB', 'Per-file cannot exceed total. A partial digest is not presented as the whole directory.'],
  ] }, image: image('aidr-skill-policy', 'Skill audit frequency, resource limits and alert rules', true) }],
  ['alerts', { title: '分类告警与继承', paragraphs: ['内容不一致、未登记/未批准/已撤销、实例未授权三类可分别选“仅记录”或“记录并告警”，同时受“生成告警”总开关控制。证据不足和查询失败保持待确认，不生成“明确不可信”的误导告警。'], bullets: ['全局默认与单机覆盖均支持这些参数，保存前查看当前值与目标值。', '单机页面展示最近客户端报告的版本、时间及配置是否相同；没有报告时显示尚未确认。', '每次调用按稳定关联身份聚合告警，重试不重复创建；后续核对变化更新告警状态，保留历史追溯。', '关闭认证核对后，新版客户端停止摘要计算，平台结论标记暂停；旧客户端需要升级才能应用新读取参数。'] },
    { title: 'Alert categories and inheritance', paragraphs: ['Content mismatch, registration/approval/revocation failures, and unauthorized instances each support record-only or record-and-alert, controlled by the Generate alerts master switch. Missing evidence and query failures stay pending rather than becoming misleading definite-failure alerts.'], bullets: ['Global defaults and device overrides support these settings; inspect current and target values before saving.', 'Device pages show latest reported version/time and whether settings match. No report remains unconfirmed.', 'Stable call identity deduplicates alerts. Retries do not create another alert; later checks update activity while preserving history.', 'Disabling checks stops digest calculation on upgraded clients and marks platform checks paused. Older clients require an update to apply new read parameters.'] }],
  ['performance', { title: '性能与缓存边界', bullets: ['同目录并发请求合并；每个采集 Store 的内存缓存最多 128 个目录、8192 份文件元数据，进程重启后重新计算。', '文件变化或策略读取上限变化会触发重算/重新判断。每次复用检查身份、大小、修改时间；macOS/Linux 另检查 change time。', 'Windows 同大小且恢复修改时间的改写可能要等到到期重读才发现。缓存用于降低后台 I/O，不能作为防篡改的调用时证明。', '平台按到期索引每批最多核对 50 条，同批复用候选与验签计算。手动重新核对读取当前平台状态；大量历史记录仍会产生排队。', '性能验收分别测量宿主工具延迟、后台摘要耗时、CPU/磁盘、队列量、ACK 延迟和告警可见时间，不把后台摘要基准当作 Hook P95/P99。'], link: link('aidr-troubleshooting', '排查摘要与认证问题') },
    { title: 'Performance and cache boundaries', bullets: ['Concurrent work for one directory is coalesced. Each collector Store caches at most 128 directories and 8192 file metadata entries; restart requires recomputation.', 'File changes or changed read limits trigger recomputation/re-evaluation. Reuse checks identity, size and mtime, plus change time on macOS/Linux.', 'On Windows, a same-size rewrite with restored mtime may remain undetected until full rehash. Caching reduces background I/O, not invocation-time tamper-proof attestation.', 'Platform refresh uses a due index with at most 50 records per batch and pass-local candidate/signature reuse. Manual recheck reads current registry state; large history can still queue.', 'Measure host tool latency, background digest time, CPU/disk, queues, ACK delay and alert visibility separately. A digest benchmark is not Hook P95/P99.'], link: link('aidr-troubleshooting', 'Troubleshoot content and certification') }],
])

